#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__))
#include <immintrin.h>
#define UTF8_HAS_AVX2_TARGET 1
#endif
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <omp.h>

static bool validate_utf8_scalar_from(const unsigned char *bytes, size_t length,
                                      size_t index) {
  while (index < length) {
    const unsigned char byte1 = bytes[index++];
    if (byte1 < 0x80) {
      continue;
    }
    if (byte1 < 0xE0) {
      if (byte1 < 0xC2 || index >= length ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    } else if (byte1 < 0xF0) {
      if (length - index < 2) {
        return false;
      }
      const unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80 ||
          (byte1 == 0xE0 && byte2 < 0xA0) ||
          (byte1 == 0xED && byte2 >= 0xA0) ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    } else {
      if (length - index < 3) {
        return false;
      }
      const unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80 || byte1 > 0xF4 ||
          (byte1 == 0xF0 && byte2 < 0x90) ||
          (byte1 == 0xF4 && byte2 > 0x8F) ||
          (bytes[index++] & 0xC0) != 0x80 ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    }
  }
  return true;
}

#if defined(UTF8_HAS_AVX2_TARGET)
__attribute__((target("avx2")))
static bool validate_utf8_avx2(const unsigned char *bytes, size_t length) {
  size_t index = 0;
  uint32_t pending = 0;
  const __m256i zero = _mm256_setzero_si256();
  const __m256i all_ones = _mm256_set1_epi8(static_cast<char>(-1));
  const __m256i minus_65 = _mm256_set1_epi8(static_cast<char>(-65));
  const __m256i minus_63 = _mm256_set1_epi8(static_cast<char>(-63));
  const __m256i minus_33 = _mm256_set1_epi8(static_cast<char>(-33));
  const __m256i minus_32 = _mm256_set1_epi8(static_cast<char>(-32));
  const __m256i minus_17 = _mm256_set1_epi8(static_cast<char>(-17));
  const __m256i minus_16 = _mm256_set1_epi8(static_cast<char>(-16));
  const __m256i minus_12 = _mm256_set1_epi8(static_cast<char>(-12));
  const __m256i minus_11 = _mm256_set1_epi8(static_cast<char>(-11));

  while (length - index >= 32) {
    const __m256i value = _mm256_loadu_si256(
        reinterpret_cast<const __m256i *>(bytes + index));

    if (pending == 0 && _mm256_movemask_epi8(value) == 0) {
      index += 32;
      continue;
    }

    const __m256i high_bytes = _mm256_cmpgt_epi8(zero, value);
    const __m256i above_bf = _mm256_cmpgt_epi8(value, minus_65);
    const __m256i continuation =
        _mm256_and_si256(high_bytes,
                         _mm256_andnot_si256(above_bf, all_ones));
    const __m256i ascii = _mm256_andnot_si256(high_bytes, all_ones);
    const __m256i lead2 = _mm256_and_si256(
        _mm256_cmpgt_epi8(value, minus_63),
        _mm256_cmpgt_epi8(minus_32, value));
    const __m256i lead3 = _mm256_and_si256(
        _mm256_cmpgt_epi8(value, minus_33),
        _mm256_cmpgt_epi8(minus_16, value));
    const __m256i lead4 = _mm256_and_si256(
        _mm256_cmpgt_epi8(value, minus_17),
        _mm256_cmpgt_epi8(minus_11, value));
    const __m256i valid = _mm256_or_si256(
        _mm256_or_si256(ascii, continuation),
        _mm256_or_si256(_mm256_or_si256(lead2, lead3), lead4));

    const uint32_t valid_bits =
        static_cast<uint32_t>(_mm256_movemask_epi8(valid));
    if (valid_bits != 0xffffffffu) {
      return false;
    }

    const __m256i restricted = _mm256_or_si256(
        _mm256_or_si256(
            _mm256_cmpeq_epi8(value, _mm256_set1_epi8(static_cast<char>(0xE0))),
            _mm256_cmpeq_epi8(value, _mm256_set1_epi8(static_cast<char>(0xED)))),
        _mm256_or_si256(
            _mm256_cmpeq_epi8(value, _mm256_set1_epi8(static_cast<char>(0xF0))),
            _mm256_cmpeq_epi8(value, _mm256_set1_epi8(static_cast<char>(0xF4)))));
    uint32_t restricted_bits =
        static_cast<uint32_t>(_mm256_movemask_epi8(restricted));
    while (restricted_bits != 0) {
      const unsigned int lane =
          static_cast<unsigned int>(__builtin_ctz(restricted_bits));
      restricted_bits &= restricted_bits - 1;
      const size_t offset = index + lane;
      if (offset + 1 >= length) {
        return false;
      }
      const unsigned char lead = bytes[offset];
      const unsigned char second = bytes[offset + 1];
      if ((lead == 0xE0 && second < 0xA0) ||
          (lead == 0xED && second >= 0xA0) ||
          (lead == 0xF0 && second < 0x90) ||
          (lead == 0xF4 && second > 0x8F)) {
        return false;
      }
    }

    const uint32_t lead2_bits =
        static_cast<uint32_t>(_mm256_movemask_epi8(lead2));
    const uint32_t lead3_bits =
        static_cast<uint32_t>(_mm256_movemask_epi8(lead3));
    const uint32_t lead4_bits =
        static_cast<uint32_t>(_mm256_movemask_epi8(lead4));
    const uint32_t continuation_bits =
        static_cast<uint32_t>(_mm256_movemask_epi8(continuation));
    const uint64_t expected_wide =
        (static_cast<uint64_t>(lead2_bits) << 1) |
        (static_cast<uint64_t>(lead3_bits) << 1) |
        (static_cast<uint64_t>(lead3_bits) << 2) |
        (static_cast<uint64_t>(lead4_bits) << 1) |
        (static_cast<uint64_t>(lead4_bits) << 2) |
        (static_cast<uint64_t>(lead4_bits) << 3) |
        static_cast<uint64_t>(pending);
    if (static_cast<uint32_t>(expected_wide) != continuation_bits) {
      return false;
    }
    pending = static_cast<uint32_t>(expected_wide >> 32);
    index += 32;
  }

  while (pending != 0) {
    if ((pending & 1u) == 0 || index >= length ||
        (bytes[index] & 0xC0) != 0x80) {
      return false;
    }
    ++index;
    pending >>= 1;
  }
  return validate_utf8_scalar_from(bytes, length, index);
}
#endif

static bool validate_utf8(const char *b, size_t length) {
  const unsigned char *bytes = reinterpret_cast<const unsigned char *>(b);
#if defined(UTF8_HAS_AVX2_TARGET)
  if (length >= 32 && __builtin_cpu_supports("avx2")) {
    return validate_utf8_avx2(bytes, length);
  }
#endif
  return validate_utf8_scalar_from(bytes, length, 0);
}

extern "C" void run(const void *input1, const void *input2, void *output,
                     int n, int parameter, int threads) {
  *static_cast<uint32_t *>(output) =
      validate_utf8(static_cast<const char *>(input1), static_cast<size_t>(n));
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

static inline bool special_second_ok(unsigned char lead, unsigned char second) {
  if (lead == 0xE0 && second < 0xA0) return false;
  if (lead == 0xED && second >= 0xA0) return false;
  if (lead == 0xF0 && second < 0x90) return false;
  if (lead == 0xF4 && second > 0x8F) return false;
  return true;
}

static bool validate_scalar_tail(const unsigned char *bytes, size_t start,
                                 size_t length, uint32_t pending) {
  for (size_t index = start; index < length; ++index) {
    const unsigned char byte = bytes[index];
    const bool needed = (pending & 1u) != 0;
    const bool continuation = (byte & 0xC0) == 0x80;

    if ((pending & 1u) == 0 && (pending >> 1) != 0) return false;
    if (needed != continuation) return false;
    if (index != 0 && !special_second_ok(bytes[index - 1], byte)) return false;

    pending >>= 1;
    if (needed) continue;
    if (byte < 0x80) continue;
    if (byte >= 0xC2 && byte <= 0xDF) {
      pending |= 1u;
    } else if (byte >= 0xE0 && byte <= 0xEF) {
      pending |= 3u;
    } else if (byte >= 0xF0 && byte <= 0xF4) {
      pending |= 7u;
    } else {
      return false;
    }
  }
  return pending == 0;
}

#if defined(__AVX2__)
#include <immintrin.h>

static bool validate_utf8(const char *input, size_t length) {
  const unsigned char *bytes = (const unsigned char *)input;
  const __m256i bias = _mm256_set1_epi8((char)0x80);
  const __m256i mask_c0 = _mm256_set1_epi8((char)0xC0);
  const __m256i mask_e0 = _mm256_set1_epi8((char)0xE0);
  const __m256i mask_f0 = _mm256_set1_epi8((char)0xF0);
  const __m256i mask_f8 = _mm256_set1_epi8((char)0xF8);
  const __m256i mask_20 = _mm256_set1_epi8((char)0x20);
  const __m256i mask_30 = _mm256_set1_epi8((char)0x30);
  const __m256i zero = _mm256_setzero_si256();
  const __m256i value_80 = _mm256_set1_epi8((char)0x80);
  const __m256i value_c0 = _mm256_set1_epi8((char)0xC0);
  const __m256i value_c1 = _mm256_set1_epi8((char)0xC1);
  const __m256i value_c2 = _mm256_set1_epi8((char)0xC2);
  const __m256i value_e0 = _mm256_set1_epi8((char)0xE0);
  const __m256i value_ed = _mm256_set1_epi8((char)0xED);
  const __m256i value_f0 = _mm256_set1_epi8((char)0xF0);
  const __m256i value_f4 = _mm256_set1_epi8((char)0xF4);
  const __m256i value_f4_unsigned = _mm256_xor_si256(value_f4, bias);

  size_t index = 0;
  uint32_t pending = 0;
  while (length - index >= 32) {
    if (index != 0 && !special_second_ok(bytes[index - 1], bytes[index])) {
      return false;
    }

    const __m256i block = _mm256_loadu_si256(
        (const __m256i *)(const void *)(bytes + index));
    if (_mm256_movemask_epi8(block) == 0) {
      if (pending != 0) return false;
      index += 32;
      continue;
    }

    const __m256i unsigned_block = _mm256_xor_si256(block, bias);
    const __m256i invalid = _mm256_or_si256(
        _mm256_or_si256(_mm256_cmpeq_epi8(block, value_c0),
                        _mm256_cmpeq_epi8(block, value_c1)),
        _mm256_cmpgt_epi8(unsigned_block, value_f4_unsigned));
    if (_mm256_movemask_epi8(invalid) != 0) return false;

    const __m256i continuations = _mm256_cmpeq_epi8(
        _mm256_and_si256(block, mask_c0), value_80);
    const __m256i leads2 = _mm256_cmpeq_epi8(
        _mm256_and_si256(block, mask_e0), value_c0);
    const __m256i leads3 = _mm256_cmpeq_epi8(
        _mm256_and_si256(block, mask_f0), value_e0);
    const __m256i leads4 = _mm256_cmpeq_epi8(
        _mm256_and_si256(block, mask_f8), value_f0);

    // Supply the upper 128-bit lane to alignr's lower lane so the shifted
    // vector also contains the real byte following position 15.
    const __m256i swapped = _mm256_permute2x128_si256(block, block, 0x01);
    const __m256i next_bytes = _mm256_alignr_epi8(swapped, block, 1);
    // Continuation validity is checked separately. Bit 5 distinguishes the
    // E0/ED boundary; bits 5:4 together distinguish the F0/F4 boundary.
    const __m256i second_bit_20 = _mm256_and_si256(next_bytes, mask_20);
    const __m256i second_bits_30 = _mm256_and_si256(next_bytes, mask_30);
    const __m256i has_bit_20 = _mm256_cmpeq_epi8(second_bit_20, mask_20);
    const __m256i lacks_bit_20 = _mm256_cmpeq_epi8(second_bit_20, zero);
    const __m256i has_any_30 = _mm256_cmpgt_epi8(second_bits_30, zero);
    const __m256i lacks_any_30 = _mm256_cmpeq_epi8(second_bits_30, zero);
    const __m256i restricted = _mm256_or_si256(
        _mm256_or_si256(
            _mm256_and_si256(_mm256_cmpeq_epi8(block, value_e0), lacks_bit_20),
            _mm256_and_si256(_mm256_cmpeq_epi8(block, value_ed), has_bit_20)),
        _mm256_or_si256(
            _mm256_and_si256(_mm256_cmpeq_epi8(block, value_f0), lacks_any_30),
            _mm256_and_si256(_mm256_cmpeq_epi8(block, value_f4), has_any_30)));
    if (((uint32_t)_mm256_movemask_epi8(restricted) & 0x7FFFFFFFu) != 0) {
      return false;
    }

    const uint32_t cont_mask = (uint32_t)_mm256_movemask_epi8(continuations);
    const uint64_t lead2_mask = (uint32_t)_mm256_movemask_epi8(leads2);
    const uint64_t lead3_mask = (uint32_t)_mm256_movemask_epi8(leads3);
    const uint64_t lead4_mask = (uint32_t)_mm256_movemask_epi8(leads4);
    const uint64_t expected_word =
        ((lead2_mask | lead3_mask | lead4_mask) << 1) |
        ((lead3_mask | lead4_mask) << 2) | (lead4_mask << 3);
    const uint32_t expected_here = (uint32_t)expected_word | pending;
    if (cont_mask != expected_here) return false;

    pending = (uint32_t)(expected_word >> 32);
    index += 32;
  }

  if (index == length) return pending == 0;
  return validate_scalar_tail(bytes, index, length, pending);
}
#elif defined(__SSE2__)
#include <emmintrin.h>

static bool validate_utf8(const char *input, size_t length) {
  const unsigned char *bytes = (const unsigned char *)input;
  const __m128i bias = _mm_set1_epi8((char)0x80);
  const __m128i mask_c0 = _mm_set1_epi8((char)0xC0);
  const __m128i mask_e0 = _mm_set1_epi8((char)0xE0);
  const __m128i mask_f0 = _mm_set1_epi8((char)0xF0);
  const __m128i mask_f8 = _mm_set1_epi8((char)0xF8);
  const __m128i value_80 = _mm_set1_epi8((char)0x80);
  const __m128i value_c0 = _mm_set1_epi8((char)0xC0);
  const __m128i value_c1 = _mm_set1_epi8((char)0xC1);
  const __m128i value_c2 = _mm_set1_epi8((char)0xC2);
  const __m128i value_e0 = _mm_set1_epi8((char)0xE0);
  const __m128i value_ed = _mm_set1_epi8((char)0xED);
  const __m128i value_f0 = _mm_set1_epi8((char)0xF0);
  const __m128i value_f4 = _mm_set1_epi8((char)0xF4);
  const __m128i value_f4_unsigned = _mm_xor_si128(value_f4, bias);
  const __m128i value_a0_unsigned =
      _mm_xor_si128(_mm_set1_epi8((char)0xA0), bias);
  const __m128i value_9f_unsigned =
      _mm_xor_si128(_mm_set1_epi8((char)0x9F), bias);
  const __m128i value_90_unsigned =
      _mm_xor_si128(_mm_set1_epi8((char)0x90), bias);
  const __m128i value_8f_unsigned =
      _mm_xor_si128(_mm_set1_epi8((char)0x8F), bias);

  size_t index = 0;
  uint32_t pending = 0;
  while (length - index >= 16) {
    if (index != 0 && !special_second_ok(bytes[index - 1], bytes[index])) {
      return false;
    }

    const __m128i block = _mm_loadu_si128(
        (const __m128i *)(const void *)(bytes + index));
    if (_mm_movemask_epi8(block) == 0) {
      if (pending != 0) return false;
      index += 16;
      continue;
    }

    const __m128i unsigned_block = _mm_xor_si128(block, bias);
    const __m128i invalid = _mm_or_si128(
        _mm_or_si128(_mm_cmpeq_epi8(block, value_c0),
                     _mm_cmpeq_epi8(block, value_c1)),
        _mm_cmpgt_epi8(unsigned_block, value_f4_unsigned));
    if (_mm_movemask_epi8(invalid) != 0) return false;

    const __m128i continuations = _mm_cmpeq_epi8(
        _mm_and_si128(block, mask_c0), value_80);
    const __m128i leads2 = _mm_cmpeq_epi8(
        _mm_and_si128(block, mask_e0), value_c0);
    const __m128i leads3 = _mm_cmpeq_epi8(
        _mm_and_si128(block, mask_f0), value_e0);
    const __m128i leads4 = _mm_cmpeq_epi8(
        _mm_and_si128(block, mask_f8), value_f0);

    const __m128i next_unsigned =
        _mm_xor_si128(_mm_srli_si128(block, 1), bias);
    const __m128i below_a0 = _mm_cmpgt_epi8(value_a0_unsigned, next_unsigned);
    const __m128i at_least_a0 = _mm_cmpgt_epi8(next_unsigned, value_9f_unsigned);
    const __m128i below_90 = _mm_cmpgt_epi8(value_90_unsigned, next_unsigned);
    const __m128i above_8f = _mm_cmpgt_epi8(next_unsigned, value_8f_unsigned);
    const __m128i restricted = _mm_or_si128(
        _mm_or_si128(
            _mm_and_si128(_mm_cmpeq_epi8(block, value_e0), below_a0),
            _mm_and_si128(_mm_cmpeq_epi8(block, value_ed), at_least_a0)),
        _mm_or_si128(
            _mm_and_si128(_mm_cmpeq_epi8(block, value_f0), below_90),
            _mm_and_si128(_mm_cmpeq_epi8(block, value_f4), above_8f)));
    if ((_mm_movemask_epi8(restricted) & 0x7FFF) != 0) return false;

    const uint32_t cont_mask = (uint32_t)_mm_movemask_epi8(continuations);
    const uint32_t lead2_mask = (uint32_t)_mm_movemask_epi8(leads2);
    const uint32_t lead3_mask = (uint32_t)_mm_movemask_epi8(leads3);
    const uint32_t lead4_mask = (uint32_t)_mm_movemask_epi8(leads4);
    const uint32_t expected_word =
        ((lead2_mask | lead3_mask | lead4_mask) << 1) |
        ((lead3_mask | lead4_mask) << 2) | (lead4_mask << 3);
    const uint32_t expected_here = (expected_word & 0xFFFFu) | pending;
    if (cont_mask != expected_here) return false;

    pending = expected_word >> 16;
    index += 16;
  }

  if (index == length) return pending == 0;
  return validate_scalar_tail(bytes, index, length, pending);
}
#else
static bool validate_utf8(const char *input, size_t length) {
  return validate_scalar_tail((const unsigned char *)input, 0, length, 0);
}
#endif

#include <cstdint>
extern "C" void run(const void *input1, const void *input2, void *output,
                    int n, int parameter, int threads) {
  *(uint32_t *)output = validate_utf8((const char *)input1, (size_t)n);
}
